const raw = $json;
const expectedRoot = ['appointments', 'generated_at', 'range', 'schema_version', 'secure_path', 'summary_by_date', 'timezone', 'total'];
const keys = raw && typeof raw === 'object' && !Array.isArray(raw) ? Object.keys(raw).sort() : [];
if (JSON.stringify(keys) !== JSON.stringify(expectedRoot.slice().sort())) throw new Error('CONTRACT_INVALID');
if (raw.schema_version !== 1 || raw.timezone !== 'America/Guatemala' || raw.secure_path !== '/dashboard') throw new Error('CONTRACT_INVALID');
if (!Number.isSafeInteger(raw.total) || raw.total <= 0 || raw.total > 10000 || !Array.isArray(raw.appointments) || raw.appointments.length !== raw.total) throw new Error('CONTRACT_INVALID');
const escapeHtml = (value) => String(value || 'No registrado').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const rows = raw.appointments.map((appointment) => {
  const appointmentKeys = appointment && typeof appointment === 'object' && !Array.isArray(appointment) ? Object.keys(appointment).sort() : [];
  if (JSON.stringify(appointmentKeys) !== JSON.stringify(['community', 'date', 'first_name', 'last_name', 'phone'])) throw new Error('CONTRACT_INVALID');
  for (const [key, max] of [['first_name', 80], ['last_name', 80], ['phone', 32], ['community', 120]]) { if (typeof appointment[key] !== 'string' || appointment[key].length > max || /[\u0000-\u001f\u007f]/.test(appointment[key])) throw new Error('CONTRACT_INVALID'); }
  if (typeof appointment.date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(appointment.date)) throw new Error('CONTRACT_INVALID');
  return '<tr><td style="padding:8px;border-bottom:1px solid #e5e7eb">' + escapeHtml(appointment.first_name) + ' ' + escapeHtml(appointment.last_name) + '</td><td style="padding:8px;border-bottom:1px solid #e5e7eb">' + escapeHtml(appointment.phone) + '</td><td style="padding:8px;border-bottom:1px solid #e5e7eb">' + escapeHtml(appointment.community) + '</td></tr>';
}).join('');
const subject = 'CAP Prenatal | Recordatorio de citas | ' + raw.range.from;
const html = '<div style="font-family:Arial,sans-serif;color:#1f2937;line-height:1.6"><h2 style="color:#7c3aed">Citas prenatales para mañana</h2><p>Se identificaron <strong>' + raw.total + '</strong> citas.</p><table style="border-collapse:collapse;width:100%;max-width:720px"><thead><tr style="background:#f3f4f6"><th style="padding:8px;text-align:left">Paciente</th><th style="padding:8px;text-align:left">Teléfono</th><th style="padding:8px;text-align:left">Comunidad</th></tr></thead><tbody>' + rows + '</tbody></table><p style="font-size:12px;color:#6b7280">Información confidencial para coordinación institucional.</p></div>';
return [{ json: { subject, html, total: raw.total } }];
